    function run(uint256 newI, uint256 newMtFeeRate) public payable {
        require(c._MAINTAINER_() != address(this), "test must not be maintainer");
        uint256 iBefore = c._I_(); if (__ESBMC_reverted()) return;
        uint256 mtBefore = c._MT_FEE_RATE_(); if (__ESBMC_reverted()) return;
        bool r1;
        c.adjustPrice(newI); bool __rev0 = __ESBMC_reverted(); if (__rev0) { r1 = true; } else { r1 = false; }
        bool r2;
        c.adjustMtFeeRate(newMtFeeRate); bool __rev1 = __ESBMC_reverted(); if (__rev1) { r2 = true; } else { r2 = false; }
        bool r3;
        c.withdrawMtFeeTotal(); bool __rev2 = __ESBMC_reverted(); if (__rev2) { r3 = true; } else { r3 = false; }
        assert(r1 && r2 && r3 && c._I_() == iBefore && c._MT_FEE_RATE_() == mtBefore);
    }
    receive() external payable {}
