// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint256 newI, uint256 newMtFeeRate) internal {
        vm.assume(c._MAINTAINER_() != address(this));
        uint256 iBefore;
        try c._I_() returns (uint256 __r) { iBefore = __r; } catch { return; }
        uint256 mtBefore;
        try c._MT_FEE_RATE_() returns (uint256 __r) { mtBefore = __r; } catch { return; }
        bool r1;
        try c.adjustPrice(newI) { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.adjustMtFeeRate(newMtFeeRate) { r2 = false; } catch { r2 = true; }
        bool r3;
        try c.withdrawMtFeeTotal() { r3 = false; } catch { r3 = true; }
        assertTrue(r1 && r2 && r3 && c._I_() == iBefore && c._MT_FEE_RATE_() == mtBefore);
    }

    function testFuzz_run(uint256 newI, uint256 newMtFeeRate) public {
        _run(newI, newMtFeeRate);
    }

    receive() external payable {}
}
